constexpr int factorial(int n) {
  if (n == 0) return 1;
  return n * factorial(n - 1); // Recursive call, allowed in constexpr if evaluated at compile time
}

int main() {
  constexpr int fact_5 = factorial(5); // Compile-time evaluation
  int fact_10 = factorial(10); // Likely runtime evaluation (due to recursion depth)
  // ...
}
